    let drop = false;
    if (effect === "shot" && !(extra && extra.target === "screen")) { drop = await canDrop(); extra = Object.assign({}, extra, { fall: drop }); }
    const msg = Object.assign({ type: "fx", effect, by: by || "", aim: !!C.face.aim }, extra || {});
    const toScreen = msg.target === "screen";
    if (FACE_FX[effect] && !toScreen) streamFace(FACE_FX[effect]);
    if (!toScreen && (C.face.aim || FACE_FX[effect])) { const f = await faceNow(); if (f) msg.face = f; }
