      const v = await req("GetVideoSettings"), W = v.baseWidth || 1920, H = v.baseHeight || 1080;
      const exists = ((await req("GetInputList")).inputs || []).some(i => i.inputName === SCREEN_NAME);
      const scenes = all ? ((await req("GetSceneList")).scenes || []).map(x => x.sceneName) : [(await req("GetCurrentProgramScene")).currentProgramSceneName];
      const settings = { is_local_file: false, url: screenLink(), width: W, height: H, reroute_audio: true };
      if (!exists) await req("CreateInput", { sceneName: scenes[0], inputName: SCREEN_NAME, inputKind: "browser_source", sceneItemEnabled: true, inputSettings: settings });
      else await req("SetInputSettings", { inputName: SCREEN_NAME, inputSettings: settings });
